param(
    [string]$Target = "",
    [switch]$NoStart,
    [switch]$Silent,
    [switch]$ValidatePayloadOnly
)

$ErrorActionPreference = 'Stop'
$ProgressPreference = 'SilentlyContinue'
[Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12

$RepoRaw = 'https://raw.githubusercontent.com/Graf-Git-Hub/Qwen_Image_2.1/main'
$Version = '8.3.4'

function Write-Step([string]$Text) {
    if (-not $Silent) { Write-Host $Text }
}

function Get-DefaultTarget {
    # Preserve the original installation location on this workstation when the parent exists.
    $paschyRoot = 'K:\Paschy_Tools_und_Projekte'
    if (Test-Path $paschyRoot) {
        return 'K:\Paschy_Tools_und_Projekte\Qwen_image2.1\Qwen-Image-2.1-Standalone'
    }
    return (Join-Path $env:LOCALAPPDATA 'Qwen-Image-2.1-Standalone')
}

function Download-File([string]$Relative, [string]$Destination, [int64]$MinBytes = 1) {
    $parent = Split-Path -Parent $Destination
    if ($parent) { New-Item -ItemType Directory -Force -Path $parent | Out-Null }

    $last = $null

    # 1) Fast path: raw.githubusercontent.com
    for ($i = 1; $i -le 3; $i++) {
        try {
            $url = "$RepoRaw/$Relative?ts=$([DateTimeOffset]::UtcNow.ToUnixTimeMilliseconds())"
            Invoke-WebRequest -UseBasicParsing -Uri $url -OutFile $Destination -TimeoutSec 180
            if (-not (Test-Path $Destination)) { throw "Download wurde nicht gespeichert: $Relative" }
            if ((Get-Item $Destination).Length -lt $MinBytes) { throw "Download ist unvollstaendig: $Relative" }
            return
        } catch {
            $last = $_
            Remove-Item -Force $Destination -ErrorAction SilentlyContinue
            Start-Sleep -Seconds 2
        }
    }

    # 2) Robust fallback: GitHub Contents API. This avoids temporary raw/CDN 404s.
    try {
        $escapedPath = ($Relative -split '/' | ForEach-Object { [Uri]::EscapeDataString($_) }) -join '/'
        $apiUrl = "https://api.github.com/repos/Graf-Git-Hub/Qwen_Image_2.1/contents/$escapedPath?ref=main"
        $headers = @{
            'User-Agent' = 'Qwen-Image-2.1-Installer'
            'Accept' = 'application/vnd.github+json'
        }
        $obj = Invoke-RestMethod -Uri $apiUrl -Headers $headers -TimeoutSec 60
        if (-not $obj.content -or $obj.encoding -ne 'base64') {
            throw "GitHub API lieferte keinen Base64-Dateiinhalt fuer: $Relative"
        }
        $bytes = [Convert]::FromBase64String(($obj.content -replace '\s',''))
        [IO.File]::WriteAllBytes($Destination, $bytes)
        if ((Get-Item $Destination).Length -lt $MinBytes) { throw "GitHub-API-Download ist unvollstaendig: $Relative" }
        return
    } catch {
        $last = $_
        Remove-Item -Force $Destination -ErrorAction SilentlyContinue
    }

    throw "Download fehlgeschlagen: $Relative`n$last"
}

function Find-Python311 {
    try {
        $p = (& py -3.11 -c "import sys;print(sys.executable)" 2>$null | Select-Object -First 1).Trim()
        if ($p -and (Test-Path $p)) { return $p }
    } catch {}

    $known = Join-Path $env:LOCALAPPDATA 'Programs\Python\Python311\python.exe'
    if (Test-Path $known) { return $known }

    try {
        $cmd = Get-Command python.exe -ErrorAction Stop
        $ver = (& $cmd.Source -c "import sys;print(f'{sys.version_info.major}.{sys.version_info.minor}')" 2>$null).Trim()
        if ($ver -eq '3.11') { return $cmd.Source }
    } catch {}

    return $null
}

if ([string]::IsNullOrWhiteSpace($Target)) { $Target = Get-DefaultTarget }
$Target = [IO.Path]::GetFullPath($Target)
$Temp = Join-Path $env:TEMP ("Qwen_Image_2_1_Install_" + [guid]::NewGuid().ToString('N'))
$Log = Join-Path $Target 'INSTALL_UPDATE.log'

New-Item -ItemType Directory -Force -Path $Target | Out-Null
New-Item -ItemType Directory -Force -Path (Join-Path $Target 'outputs') | Out-Null
New-Item -ItemType Directory -Force -Path (Join-Path $Target 'hf_cache') | Out-Null
New-Item -ItemType Directory -Force -Path $Temp | Out-Null

Start-Transcript -Path $Log -Append | Out-Null

try {
    if (-not $Silent) {
        Write-Host '============================================================'
        Write-Host '  Qwen Image 2.1 - INSTALLATION / UPDATE'
        Write-Host '============================================================'
        Write-Host "Ziel: $Target"
        Write-Host ''
    }

    Write-Step '[1/8] Entpacke eingebettete Programmdateien ...'
    # Die komplette kleine App-Payload steckt im Installer selbst.
    # Dadurch gibt es bei der Installation keine fragilen GitHub-Downloads fuer Einzeldateien mehr.
    $appB64Parts = @(
        '',
        '',
        '',
        ''
    )
    $gzPath = Join-Path $Temp 'qwen_app.py.gz'
    $appTemp = Join-Path $Temp 'qwen_app.py'
    [IO.File]::WriteAllBytes($gzPath, [Convert]::FromBase64String(($appB64Parts -join '')))

    $inStream = [IO.File]::OpenRead($gzPath)
    try {
        $gzip = New-Object IO.Compression.GzipStream($inStream, [IO.Compression.CompressionMode]::Decompress)
        try {
            $outStream = [IO.File]::Create($appTemp)
            try { $gzip.CopyTo($outStream) } finally { $outStream.Dispose() }
        } finally { $gzip.Dispose() }
    } finally { $inStream.Dispose() }

    $appText = [IO.File]::ReadAllText($appTemp, [Text.Encoding]::UTF8)

    # Queue-Medien V8.3.2: direkt laden, damit aktives Video und wartendes Standbild sicher sichtbar sind.
    $appText = $appText.Replace('APP_VERSION = "8.2.0"', 'APP_VERSION = "8.3.4"')
    $appText = $appText.Replace('V8.2.0 · CLEAN · PORT 7862', 'V8.3.4 · CLEAN · PORT 7862')
    $appText = $appText.Replace('V8.2.0', 'V8.3.4')

    $oldQueueDecl = @'
let queue=[], queueRunning=false, queueCounter=1, loadingVideoBlobUrl=null, queueStillBlobUrl=null;
'@
    $newQueueDecl = @'
let queue=[], queueRunning=false, queueCounter=1; const QUEUE_MEDIA_VERSION='8.3.4';
'@
    $appText = $appText.Replace($oldQueueDecl.Trim(), $newQueueDecl.Trim())

    $oldEnsure = @'
async function ensureQueueAssets(){if(!loadingVideoBlobUrl){const r=await fetch('/loading-video?ts='+Date.now(),{cache:'no-store'});if(r.ok)loadingVideoBlobUrl=URL.createObjectURL(await r.blob())}if(!queueStillBlobUrl){const r=await fetch('/queue-still?ts='+Date.now(),{cache:'no-store'});if(r.ok)queueStillBlobUrl=URL.createObjectURL(await r.blob())}}
'@
    $newEnsure = @'
function queueVideoUrl(){return '/loading-video?v='+encodeURIComponent(QUEUE_MEDIA_VERSION)}
function queueStillUrl(){return '/queue-still?v='+encodeURIComponent(QUEUE_MEDIA_VERSION)}
async function ensureQueueAssets(){try{fetch(queueVideoUrl(),{cache:'no-store'}).catch(()=>{})}catch(e){}try{const im=new Image();im.src=queueStillUrl()}catch(e){}}
function makeQueueStill(){const im=document.createElement('img');im.src=queueStillUrl();im.alt='Wartender Auftrag';im.loading='eager';return im}
function makeQueueVideo(card){const v=document.createElement('video');v.src=queueVideoUrl();v.poster=queueStillUrl();v.autoplay=true;v.loop=true;v.muted=true;v.defaultMuted=true;v.playsInline=true;v.preload='auto';v.setAttribute('muted','');v.setAttribute('playsinline','');v.setAttribute('autoplay','');v.setAttribute('loop','');const tryPlay=()=>v.play().catch(()=>{});v.addEventListener('loadeddata',tryPlay,{once:true});v.addEventListener('canplay',tryPlay,{once:true});v.addEventListener('error',()=>{if(v.parentNode===card){card.insertBefore(makeQueueStill(),v);v.remove()}},{once:true});setTimeout(tryPlay,0);setTimeout(tryPlay,250);return v}
'@
    $appText = $appText.Replace($oldEnsure.Trim(), $newEnsure.Trim())

    $oldRender = @'
function renderQueue(){const head=$('queueHead'),grid=$('queueGrid');head.classList.toggle('show',queue.length>0);$('queueCount').textContent=queue.length?`${queue.length} Auftrag${queue.length===1?'':'e'}`:'';grid.innerHTML='';queue.forEach((job,idx)=>{const d=document.createElement('div');d.className='card queue-card '+(idx===0&&queueRunning?'active':'waiting');if(idx===0&&queueRunning&&loadingVideoBlobUrl){const v=document.createElement('video');v.src=loadingVideoBlobUrl;v.autoplay=true;v.loop=true;v.muted=true;v.playsInline=true;d.appendChild(v);setTimeout(()=>v.play().catch(()=>{}),50)}else{const im=document.createElement('img');im.src=queueStillBlobUrl||'/queue-still';d.appendChild(im)}const info=document.createElement('div');info.className='queue-info';info.textContent=idx===0&&queueRunning?'läuft gerade':'wartet';d.appendChild(info);const ix=document.createElement('div');ix.className='queue-index';ix.textContent='#'+job.id;d.appendChild(ix);const p=document.createElement('div');p.className='queue-prompt';p.textContent=(job.count>1?`${job.count} Bilder · `:'')+job.prompt;d.appendChild(p);grid.appendChild(d)})}
'@
    $newRender = @'
function renderQueue(){const head=$('queueHead'),grid=$('queueGrid');head.classList.toggle('show',queue.length>0);$('queueCount').textContent=queue.length?(String(queue.length)+' Auftrag'+(queue.length===1?'':'e')):'';grid.innerHTML='';queue.forEach((job,idx)=>{const active=idx===0&&queueRunning;const d=document.createElement('div');d.className='card queue-card '+(active?'active':'waiting');d.appendChild(active?makeQueueVideo(d):makeQueueStill());const info=document.createElement('div');info.className='queue-info';info.textContent=active?'läuft gerade':'wartet';d.appendChild(info);const ix=document.createElement('div');ix.className='queue-index';ix.textContent='#'+job.id;d.appendChild(ix);const p=document.createElement('div');p.className='queue-prompt';p.textContent=(job.count>1?(String(job.count)+' Bilder · '):'')+job.prompt;d.appendChild(p);grid.appendChild(d)})}
'@
    $appText = $appText.Replace($oldRender.Trim(), $newRender.Trim())

    $oldProcess = @'
async function processQueue(){if(queueRunning||!queue.length)return;queueRunning=true;await ensureQueueAssets().catch(()=>{});renderQueue();const job=queue[0];
'@
    $newProcess = @'
async function processQueue(){if(queueRunning||!queue.length)return;queueRunning=true;renderQueue();ensureQueueAssets().catch(()=>{});const job=queue[0];
'@
    $appText = $appText.Replace($oldProcess.Trim(), $newProcess.Trim())


    # Qwen-Modell direkt beim Serverstart im Hintergrund laden.
    # So kann der Benutzer sofort den Prompt schreiben, waehrend das Modell bereits laedt.
    if ($appText -notmatch '_autoload_model_on_startup') {
        $autoloadBlock = @'
@app.on_event("startup")
async def _autoload_model_on_startup():
    import threading as _autoload_threading
    def _autoload_runner():
        try:
            load_model()
        except Exception as exc:
            print(f"[AUTOLOAD] Modell konnte nicht automatisch geladen werden: {exc}", flush=True)
    _autoload_threading.Thread(target=_autoload_runner, daemon=True, name="qwen-model-autoload").start()

'@
        $mainMarker = 'if __name__ == "__main__":'
        if (-not $appText.Contains($mainMarker)) {
            throw 'Autoload-Marker __main__ wurde in qwen_app.py nicht gefunden.'
        }
        $appText = $appText.Replace($mainMarker, $autoloadBlock + $mainMarker)
    }

    if ($appText -notmatch 'function makeQueueVideo' -or
        $appText -notmatch 'function makeQueueStill' -or
        $appText -notmatch 'queueVideoUrl') {
        throw 'Queue-Medien-Patch konnte nicht angewendet werden.'
    }
    if ($appText -notmatch 'APP_VERSION = "8.3.4"') {
        throw 'App-Version wurde nicht auf 8.3.4 aktualisiert.'
    }
    if ($appText -notmatch 'V8.3.4') {
        throw 'Sichtbare UI-Version wurde nicht auf V8.3.4 aktualisiert.'
    }
    if ($appText -notmatch '_autoload_model_on_startup') {
        throw 'Modell-Autoload fehlt in qwen_app.py.'
    }
    if ($appText.Contains([char]0x00C3) -or $appText.Contains([char]0x00C2)) {
        throw 'UTF-8-Pruefung fehlgeschlagen: Mojibake in qwen_app.py erkannt.'
    }
    [IO.File]::WriteAllText($appTemp, $appText, (New-Object Text.UTF8Encoding($false)))

    if ($appText -notmatch 'QwenImage21Pipeline' -or $appText -notmatch 'FastAPI') {
        throw 'qwen_app.py ist unvollstaendig oder beschaedigt.'
    }

    Copy-Item -Force $appTemp (Join-Path $Target 'qwen_app.py')
    [IO.File]::WriteAllBytes((Join-Path $Target 'START_QWEN_IMAGE_2_1.cmd'), [Convert]::FromBase64String(''))
    [IO.File]::WriteAllBytes((Join-Path $Target 'update_and_start.ps1'), [Convert]::FromBase64String(''))
    [IO.File]::WriteAllBytes((Join-Path $Target 'loading_matrix.mp4'), [Convert]::FromBase64String(''))
    [IO.File]::WriteAllBytes((Join-Path $Target 'queue_wait.webp'), [Convert]::FromBase64String(''))
    "$Version" | Set-Content -Encoding ASCII (Join-Path $Temp 'VERSION.txt')

    if (-not (Test-Path (Join-Path $Target 'OLLAMA_URL.txt'))) {
        'http://127.0.0.1:11434' | Set-Content -Encoding UTF8 (Join-Path $Target 'OLLAMA_URL.txt')
    }
    if (-not (Test-Path (Join-Path $Target 'PROMPT_AI_MODEL.txt'))) {
        '' | Set-Content -Encoding UTF8 (Join-Path $Target 'PROMPT_AI_MODEL.txt')
    }

    if ($ValidatePayloadOnly) {
        Write-Host 'PAYLOAD_OK'
        return
    }

    Write-Step '[2/8] Pruefe NVIDIA ...'
    if (Get-Command nvidia-smi.exe -ErrorAction SilentlyContinue) {
        & nvidia-smi.exe --query-gpu=name,memory.total,driver_version --format=csv,noheader
    } else {
        Write-Warning 'nvidia-smi wurde nicht gefunden. Bitte einen aktuellen NVIDIA-Treiber installieren.'
    }

    Write-Step '[3/8] Pruefe Python 3.11 ...'
    $venvPython = Join-Path $Target 'venv\Scripts\python.exe'
    if (-not (Test-Path $venvPython)) {
        $python = Find-Python311
        if (-not $python) {
            if (Get-Command winget.exe -ErrorAction SilentlyContinue) {
                Write-Step 'Python 3.11 fehlt. Installiere es automatisch mit winget ...'
                & winget.exe install --id Python.Python.3.11 -e --scope user --silent --accept-package-agreements --accept-source-agreements
                if ($LASTEXITCODE -ne 0) { Write-Warning "winget meldete Fehlercode $LASTEXITCODE. Versuche Fallback." }
                $python = Find-Python311
            }
        }
        if (-not $python) {
            Write-Step 'Winget war nicht verfuegbar oder schlug fehl. Lade Python 3.11.9 direkt ...'
            $pyInstaller = Join-Path $Temp 'python-3.11.9-amd64.exe'
            Invoke-WebRequest -UseBasicParsing -Uri 'https://www.python.org/ftp/python/3.11.9/python-3.11.9-amd64.exe' -OutFile $pyInstaller -TimeoutSec 300
            $proc = Start-Process -FilePath $pyInstaller -ArgumentList '/quiet','InstallAllUsers=0','PrependPath=1','Include_launcher=1','Include_pip=1' -Wait -PassThru
            if ($proc.ExitCode -ne 0) { throw "Python-Installation fehlgeschlagen: $($proc.ExitCode)" }
            $python = Find-Python311
        }
        if (-not $python) { throw 'Python 3.11 konnte nicht gefunden oder installiert werden.' }

        Write-Step '[4/8] Erstelle virtuelle Python-Umgebung ...'
        & $python -m venv (Join-Path $Target 'venv')
        if ($LASTEXITCODE -ne 0 -or -not (Test-Path $venvPython)) { throw 'venv konnte nicht erstellt werden.' }
    } else {
        Write-Step '[4/8] Vorhandene virtuelle Python-Umgebung gefunden.'
    }

    Write-Step '[5/8] Pruefe / installiere Python-Pakete ...'
    $packageCheck = @'
import sys
ok = True
try:
 import torch, fastapi, uvicorn, transformers, accelerate, huggingface_hub
 from PIL import Image
 from diffusers import QwenImage21Pipeline
 from packaging.version import Version
 ok = Version(transformers.__version__) >= Version("5.17")
except Exception:
 ok = False
sys.exit(0 if ok else 1)
'@
    & $venvPython -c $packageCheck
    if ($LASTEXITCODE -ne 0) {
        & $venvPython -m pip install --upgrade pip setuptools wheel packaging
        if ($LASTEXITCODE -ne 0) { throw 'pip konnte nicht aktualisiert werden.' }

        & $venvPython -m pip install --upgrade torch torchvision --index-url https://download.pytorch.org/whl/cu126
        if ($LASTEXITCODE -ne 0) { throw 'PyTorch konnte nicht installiert werden.' }

        & $venvPython -m pip install --upgrade 'transformers>=5.17' accelerate pillow fastapi uvicorn python-multipart huggingface_hub hf_xet safetensors sentencepiece packaging
        if ($LASTEXITCODE -ne 0) { throw 'Python-Abhaengigkeiten konnten nicht installiert werden.' }

        & $venvPython -m pip install --upgrade 'https://github.com/huggingface/diffusers/archive/refs/heads/main.zip'
        if ($LASTEXITCODE -ne 0) { throw 'Diffusers konnte nicht installiert werden.' }
    }

    Write-Step '[6/8] Pruefe Anwendung ...'
    & $venvPython -m py_compile (Join-Path $Target 'qwen_app.py')
    if ($LASTEXITCODE -ne 0) { throw 'qwen_app.py hat einen Python-Syntaxfehler.' }

    Write-Step '[7/8] Pruefe Qwen-Image-2.1 Modell ...'
    $modelIndex = Join-Path $Target 'model\model_index.json'
    if (-not (Test-Path $modelIndex)) {
        Write-Host ''
        Write-Host 'Das grosse Qwen-Image-2.1-Modell wird jetzt heruntergeladen.'
        Write-Host 'Das kann lange dauern. Ein abgebrochener Download kann beim naechsten Start fortgesetzt werden.'
        Write-Host ''
        $modelCode = "from huggingface_hub import snapshot_download; snapshot_download(repo_id='Qwen/Qwen-Image-2.1', local_dir=r'''$($Target)\model''')"
        & $venvPython -c $modelCode
        if ($LASTEXITCODE -ne 0 -or -not (Test-Path $modelIndex)) { throw 'Qwen-Image-2.1 Modell konnte nicht vollstaendig heruntergeladen werden.' }
    } else {
        Write-Step 'Modell ist bereits vorhanden.'
    }

    Write-Step '[8/8] Erstelle Desktop-Verknuepfung ...'
    # VERSION is written last. An interrupted install therefore never looks falsely current.
    Copy-Item -Force (Join-Path $Temp 'VERSION.txt') (Join-Path $Target 'VERSION.txt')
    Copy-Item -Force $PSCommandPath (Join-Path $Target 'install.ps1')

    $desktop = [Environment]::GetFolderPath('Desktop')
    $shell = New-Object -ComObject WScript.Shell
    $shortcut = $shell.CreateShortcut((Join-Path $desktop 'Qwen Image 2.1.lnk'))
    $shortcut.TargetPath = Join-Path $Target 'START_QWEN_IMAGE_2_1.cmd'
    $shortcut.WorkingDirectory = $Target
    $shortcut.IconLocation = "$env:SystemRoot\System32\shell32.dll,167"
    $shortcut.Description = 'Qwen Image 2.1 - automatische Update-Pruefung beim Start'
    $shortcut.Save()

    Write-Host ''
    Write-Host '============================================================'
    Write-Host "  FERTIG - Qwen Image 2.1 $Version"
    Write-Host '============================================================'
    Write-Host "Installiert in: $Target"
    Write-Host 'Desktop-Verknuepfung: Qwen Image 2.1'
    Write-Host ''

    if (-not $NoStart) {
        Start-Process -FilePath (Join-Path $Target 'START_QWEN_IMAGE_2_1.cmd') -WorkingDirectory $Target -ArgumentList '/skipupdate'
    }
}
catch {
    Write-Host ''
    Write-Host '============================================================' -ForegroundColor Red
    Write-Host '  INSTALLATION / UPDATE FEHLGESCHLAGEN' -ForegroundColor Red
    Write-Host '============================================================' -ForegroundColor Red
    Write-Host $_.Exception.Message -ForegroundColor Red
    Write-Host "Logdatei: $Log"
    exit 1
}
finally {
    try { Stop-Transcript | Out-Null } catch {}
    Remove-Item -Recurse -Force $Temp -ErrorAction SilentlyContinue
}

exit 0
